function TrailStageMainCellNode:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    if isNull(self.CommonPlayerHeadNode.Env) then
        self.CommonPlayerHeadNode:Init()
    end
end

function TrailStageMainCellNode:UpdateContent(data)
    --printInfo("data==="..table.dump(data))
    --首先判断是否是最高或者最低段位的
    local isMaxSegment = trailBattleMgr.isMaxSegment
    local isMinSegment = trailBattleMgr.isMinSegment
    local curSegment = trailBattleMgr:GetMySegment()
    local segmentData = trailBattleMgr:GetSegmentRewardVoByRefId(curSegment)
    local isArrow = data.order % 2 == 1 --奇数带箭头，偶数不带箭头
    self.ItemHeadGroup.anchoredPosition = Vector2.New(data.posX, self.ItemHeadGroup.anchoredPosition.y)
    local isUnlisted = data.score <= 0
    KTool.SetActive(self.ImgRegion2, false)
    KTool.SetActive(self.ImgArrowLeft, isArrow)
    KTool.SetActive(self.ImgArrowRight, isArrow)
    KTool.SetActive(self.ImageSymbol, isArrow)
    KTool.SetActive(self.ImgArrowMiddle, not isArrow)
    KTool.SetActive(self.TextNotOnTheList, false)
    KTool.SetActive(self.TxtRanking, true)
    KTool.SetActive(self.Content, true)

    if data.isLast then
        self.TxtName.text =  data.name
        KTool.SetActive(self.TxtRanking, not isUnlisted)
        KTool.SetActive(self.TextNotOnTheList, isUnlisted)
        if not isUnlisted then
            self.TxtRanking.text = data.order
        else
            self.CommonPlayerHeadNode.Env:FreshAvatarFrame(data.avatar, data.avatarFrame)
        end
        local unlistedNum = trailBattleMgr:GetUnlistedNumber(1, 20)
        self.TxtRegion2.text = string.format("本组共有%s人未上榜", unlistedNum)--1到20名
        KTool.SetActive(self.ImgRegion2, true)
        KTool.SetActive(self.score, not isUnlisted)
        if not isUnlisted then
            self.TxtScore.text = data.score
        end
        local statusLast = 0
        if isMinSegment then
            statusLast = ImgRegion1SwitchStatus.KeepGrade
        else
            statusLast = ImgRegion1SwitchStatus.DownGrade
        end
        self:FreshGradeImageStatus(statusLast)
        self:FreshHeadTailStatus(data, statusLast)
        KTool.SetActive(self.Content, isUnlisted)
        KTool.SetActive(self.ImgRegion2, unlistedNum ~= 0)
        return
    end
    self.TxtRanking.text = data.order
    self.TxtName.text = isUnlisted and localize("空缺") or data.name
    KTool.SetActive(self.score, not isUnlisted)
    KTool.SetActive(self.Empty, isUnlisted)
    KTool.SetActive(self.PlayerHeadNode, not isUnlisted)
    if not isUnlisted then
        local myPlayerId = checkNumber(GameUtils.GetPlayerId())
        local isMe = myPlayerId == checkNumber(data.playerId)
        KTool.SetActive(self.ImgMyself, isMe)
        self.TxtScore.text = data.score
        self.CommonPlayerHeadNode.Env:FreshAvatarFrame(data.avatar, data.avatarFrame)
        --self.CommonPlayerHeadNode.Env:SetCallBack(function()
        --    GameUtils.ShowPlayerInfo(data.playerId, {
        --        {id = Constants.UITypeIds.TrailStageMain}
        --    })
        --end)
    end
    if isMaxSegment then--最高段位 保级降级两种情况
        local keepArea = segmentData.keepGrade
        local downArea = segmentData.downGrade
        local isKeepGrade = self:IsInArea(data.order, keepArea[1], keepArea[2])
        local isDownGrade = self:IsInArea(data.order, downArea[1], downArea[2])
