function TrailStageMainCellNode:FreshGradeImageStatus(status)
    self.ImgChangeBG.Status = status
    self.ImgArrowLeft.Status = status
    self.ImgArrowRight.Status = status
    self.ImageSymbol.Status = status
    self.ImgArrowMiddle.Status = status
end

function TrailStageMainCellNode:FreshHeadTailStatus(data, status)
    if data.order == 1 and isNull(data.isLast) then
        KTool.SetActive(self.HeadBgNode, true)
        KTool.SetActive(self.TailBgNode, false)
        self.HeadBg1.Status = status
        self.HeadBg2.Status = status
        self.HeadBg3.Status = status
    elseif data.isLast then
        KTool.SetActive(self.HeadBgNode, false)
        KTool.SetActive(self.TailBgNode, true)
        self.TailBg1.Status = status
        self.TailBg2.Status = status
        self.TailBg3.Status = status
    else
        KTool.SetActive(self.HeadBgNode, false)
        KTool.SetActive(self.TailBgNode, false)
    end
end

---@param position number
function TrailStageMainCellNode:UpdatePosition(position)
    self.Cell:Play(CS.UnityEngine.Animator.StringToHash("TrailStageMainFancy"), -1, position)
    self.Cell.speed = 0
end

---if minNum <= targetNum <= maxNum then
---     return true
---else
---     return false
---end
function TrailStageMainCellNode:IsInArea(targetNum, minNum, maxNum)
    targetNum = checkNumber(targetNum)
    minNum = checkNumber(minNum)
    maxNum = checkNumber(maxNum)
    if targetNum >= minNum and targetNum <= maxNum then
        return true
    else
        return false
    end
end

function TrailStageMainCellNode:OnDestory()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return TrailStageMainCellNode